1	import Link from "next/link";
2	import { db } from "@/lib/db";
3	import { requireUser } from "@/lib/auth";
4	import { AutoRefresh } from "@/components/AutoRefresh";
5	import { PageHeader, EmptyState } from "@/components/ui/primitives";
6	import { ServersList, type ServerRow } from "@/components/customer/ServersList";
7	import { effectiveDiskGB } from "@/lib/extra-disk";
8	
9	export const dynamic = "force-dynamic";
10	
11	export default async function ServersPage() {
12	  const user = await requireUser();
13	  const servers = await db.server.findMany({
14	    where: { userId: user.id },
15	    include: { plan: true, osTemplate: true, project: true },
16	    orderBy: { createdAt: "desc" },
17	  });
18	
19	  const transitional = servers.some((s) =>
20	    ["PENDING", "PROVISIONING", "REINSTALLING", "DELETING"].includes(s.status)
21	  );
22	
23	  const rows: ServerRow[] = servers.map((s) => ({
24	    id: s.id,
25	    hostname: s.hostname,
26	    status: s.status,
27	    isFree: s.isFree,
28	    // Effective disk = plan allowance + any separately-purchased extra disk.
29	    planLine: `${s.plan.name} · ${s.plan.cpuCores} vCPU · ${s.plan.ramMB / 1024} GB · ${effectiveDiskGB(s.plan.diskGB, s.extraDiskGB)} GB`,
30	    osName: s.osTemplate.name,
31	    project: s.project ? { name: s.project.name, color: s.project.color } : null,
32	    endpoint: s.sshPort ? `${process.env.PUBLIC_IP}:${s.sshPort}` : null,
33	    created: s.createdAt.toISOString().slice(0, 10),
34	  }));
35	
36	  return (
37	    <div className="space-y-6">
38	      {transitional && <AutoRefresh />}
39	      <PageHeader title="Servers" sub="All virtual machines on your account.">
40	        <Link href="/dashboard/deploy" className="btn-primary">
41	          + Deploy server
42	        </Link>
43	      </PageHeader>
44	
45	      {servers.length === 0 ? (
46	        <EmptyState
47	          title="No servers yet"
48	          sub="Deploy your first NVMe-backed VPS — it takes under two minutes from click to SSH."
49	          action={
50	            <Link href="/dashboard/deploy" className="btn-primary">
51	              Deploy your first server
52	            </Link>
53	          }
54	        />
55	      ) : (
56	        <ServersList servers={rows} />
57	      )}
58	    </div>
59	  );
60	}
