1	import { notFound } from "next/navigation";
2	import { db } from "@/lib/db";
3	import { requireUser } from "@/lib/auth";
4	import { serverRootPassword } from "@/lib/sftp";
5	import { vmStatus, listSnapshots, listBackups } from "@/lib/proxmox";
6	import { AutoRefresh } from "@/components/AutoRefresh";
7	import { ServerControls } from "@/components/ServerControls";
8	import { RenewalCard } from "@/components/SubscriptionControls";
9	import { StatusDot, Badge, fmtBytes, fmtMoney } from "@/components/ui/primitives";
10	import { MeterBar } from "@/components/ui/charts";
11	import { ServerTabs } from "@/components/customer/ServerTabs";
12	import { MetricsPanel } from "@/components/customer/MetricsPanel";
13	import { DiskUsageChart } from "@/components/customer/DiskUsageChart";
14	import { ServerRename } from "@/components/customer/ServerRename";
15	import { Console } from "@/components/customer/Console";
16	import { OpenTerminalButton } from "@/components/customer/OpenTerminalButton";
17	import { FileManager } from "@/components/customer/FileManager";
18	import { CopyText, RevealPassword, ResetPasswordButton } from "@/components/customer/ServerAccess";
19	import { ProjectAssign } from "@/components/customer/ProjectAssign";
20	import { CreateSnapshotForm, SnapshotActions } from "@/components/customer/SnapshotControls";
21	import { CreateBackupButton } from "@/components/customer/BackupControls";
22	import { AddForwardForm, DeleteForwardButton, FirewallPresets } from "@/components/customer/NetworkingControls";
23	import { ResizePicker } from "@/components/customer/ResizePicker";
24	import { ResizeDown } from "@/components/customer/ResizeDown";
25	import { AddStorage } from "@/components/customer/AddStorage";
26	import { extraDiskPerGbCents } from "@/lib/disk-expand";
27	import { renewalQuote } from "@/lib/renewal-quote";
28	import { dedicatedIpMonthlyCents } from "@/lib/dedicated-ip";
29	import { effectiveDiskGB } from "@/lib/extra-disk";
30	import { ReinstallOs } from "@/components/customer/ReinstallOs";
31	import { BackupSchedule } from "@/components/customer/BackupSchedule";
32	import { backupScheduleHealth } from "@/lib/backup-verify";
33	import { ActivityTimeline } from "@/components/customer/ActivityTimeline";
34	import { SftpAccess } from "@/components/customer/SftpAccess";
35	import { GameAutoUpdate } from "@/components/customer/GameAutoUpdate";
36	import { BackupRestore } from "@/components/customer/BackupRestore";
37	import { GameSettings } from "@/components/customer/GameSettings";
38	import { ControlPanel } from "@/components/customer/cpanel/ControlPanel";
39	import { GAME_FAMILIES, type GameFamily } from "@/lib/games";
40	import { familyFor, schemaFor, isValidVariant, validateConfig } from "@/lib/game-config";
41	
42	export const dynamic = "force-dynamic";
43	
44	function fmtUptime(seconds: number): string {
45	  if (!seconds || seconds <= 0) return "—";
46	  const d = Math.floor(seconds / 86400);
47	  const h = Math.floor((seconds % 86400) / 3600);
48	  const m = Math.floor((seconds % 3600) / 60);
49	  return d > 0 ? `${d}d ${h}h ${m}m` : h > 0 ? `${h}h ${m}m` : `${m}m`;
50	}
51	
52	type LiveStats = {
53	  cpu?: number;
54	  mem?: number;
55	  maxmem?: number;
56	  uptime?: number;
57	  netin?: number;
58	  netout?: number;
59	} | null;
60	
61	export default async function ServerPage({
62	  params,
63	  searchParams,
64	}: {
65	  params: Promise<{ id: string }>;
66	  searchParams: Promise<{ tab?: string }>;
67	}) {
68	  const [{ id }, { tab }] = await Promise.all([params, searchParams]);
69	  const user = await requireUser();
70	  const server = await db.server.findUnique({
71	    where: { id },
72	    include: {
73	      plan: true,
74	      osTemplate: true,
75	      project: true,
76	      portForwards: { orderBy: { publicPort: "asc" } },
77	      jobs: { orderBy: { createdAt: "desc" }, take: 20 },
78	      dedicatedIp: true,
79	      // Needed to price a renewal correctly: a game server bills its game plan's
80	      // flat price, not the base VPS plan's term price.
81	      gamePlan: true,
82	    },
83	  });
84	  if (!server || (server.userId !== user.id && user.role !== "ADMIN")) notFound();
85	
86	  // Root password may be stored encrypted-at-rest (rootPasswordEnc); resolve the
87	  // display value through the decrypt fallback (legacy plaintext rows still work).
88	  const rootPassword = serverRootPassword(server);
89	
90	  const [projects, activePlans, osTemplates, extraDiskPriceCents] = await Promise.all([
91	    db.project.findMany({ where: { userId: server.userId }, orderBy: { name: "asc" } }),
92	    db.plan.findMany({ where: { active: true }, orderBy: { sortOrder: "asc" } }),
93	    db.osTemplate.findMany({
94	      where: { active: true, category: "PLAIN_OS" },
95	      orderBy: [{ sortOrder: "asc" }, { name: "asc" }],
96	    }),
97	    extraDiskPerGbCents(),
98	  ]);
99	
100	  // What "Renew now" will actually charge, priced through the SAME function the
101	  // action charges through, so the button cannot quote one figure and take
102	  // another. See lib/renewal-quote.ts for the incident.
103	  const renewQuote = renewalQuote(
104	    {
105	      termMonths: server.termMonths,
106	      extraDiskGB: server.extraDiskGB,
107	      plan: { name: server.plan.name, priceCents: server.plan.priceCents },
108	      // A game server is sold at its game plan's flat price, NOT the base VPS
109	      // plan it happens to be built on. Omitting this quoted an $8.99 renewal for
110	      // a $4.99 product.
111	      gamePlan: server.gamePlan
112	        ? { name: server.gamePlan.name, priceCents: server.gamePlan.priceCents, termMonths: server.gamePlan.termMonths }
113	        : null,
114	      dedicatedIp: server.dedicatedIp,
115	    },
116	    {
117	      ipMonthlyCents: server.dedicatedIp ? await dedicatedIpMonthlyCents() : 0,
118	      extraDiskPerGbCents: extraDiskPriceCents,
119	    },
120	  );
121	
122	  // The server's REAL disk: plan allowance + any separately-purchased extra disk.
123	  // Every disk figure on this page uses this, never `plan.diskGB` on its own.
124	  const totalDiskGB = effectiveDiskGB(server.plan.diskGB, server.extraDiskGB);
125	
126	  const publicIp = process.env.PUBLIC_IP ?? "";
127	  const transitional = ["PENDING", "PROVISIONING", "REINSTALLING", "DELETING"].includes(server.status);
128	  const busy =
129	    transitional || server.jobs.some((j) => j.status === "QUEUED" || j.status === "RUNNING");
130	  const steady = ["RUNNING", "STOPPED"].includes(server.status);
131	
132	  let live: LiveStats = null;
133	  let snapshots: { name: string; snaptime?: number; description?: string }[] = [];
134	  let backups: { volid: string; ctime?: number; size?: number }[] = [];
135	  let pveUnavailable = false;
136	
137	  if (server.vmid && steady) {
138	    const results = await Promise.allSettled([
139	      vmStatus(server.vmid),
140	      listSnapshots(server.vmid),
141	      listBackups(server.vmid),
142	    ]);
143	    if (results[0].status === "fulfilled") live = results[0].value as LiveStats;
144	    if (results[1].status === "fulfilled") snapshots = results[1].value as typeof snapshots;
145	    if (results[2].status === "fulfilled") backups = results[2].value as typeof backups;
146	    pveUnavailable = results.some((r) => r.status === "rejected");
147	  }
148	
149	  const sshCommand = server.sshPort ? `ssh root@${publicIp} -p ${server.sshPort}` : null;
150	
151	  // Single-item terminal list for this server — connect string computed the
152	  // same way as the Claude Code hub (dedicated IP → own IP, else NAT SSH port).
153	  const terminalServers = [
154	    {
155	      id: server.id,
156	      hostname: server.hostname,
157	      connect: server.dedicatedIp
158	        ? `ssh root@${server.dedicatedIp.address}`
159	        : `ssh -p ${server.sshPort ?? 22} root@${publicIp || "YOUR_SERVER_IP"}`,
160	    },
161	  ];
162	
163	  // SFTP/SSH connection details: dedicated-IP servers connect to their own IP on
164	  // port 22; NAT servers use the platform public IP + the forwarded SSH port.
165	  const dedicated = !!server.dedicatedIp;
166	  const sftpHost = dedicated ? server.dedicatedIp!.address : publicIp || null;
167	  const sftpPort = dedicated ? 22 : server.sshPort;
168	  const isGameServer = GAME_FAMILIES.includes(server.osTemplate.family as GameFamily);
169	
170	  // Per-game customization (only for game servers with a customization schema).
171	  const gameFamily = familyFor(server);
172	  const gameSchema = schemaFor(gameFamily);
173	  const gameVariant =
174	    gameSchema && server.gameVariant && isValidVariant(gameFamily!, server.gameVariant)
175	      ? server.gameVariant
176	      : gameSchema?.defaultVariant ?? "";
177	  const gameValidated = gameFamily
178	    ? validateConfig(gameFamily, (server.gameConfig as Record<string, unknown> | null) ?? {})
179	    : null;
180	  const gameValues = gameValidated && gameValidated.ok ? gameValidated.values : {};
181	
182	  /* ---------- Tab: Overview ---------- */
183	  const overview = (
184	    // `grid-cols-1` is load-bearing below `md`. With no base template the browser
185	    // creates an IMPLICIT `auto` track, sized to min-content and unclampable: at
186	    // 390px the rehearsal measured it at 530px — the `ssh root@… -p …` <code> and
187	    // the SFTP/SSH credentials are unbreakable strings — scrolling the whole page
188	    // 156px sideways. `grid-cols-1` compiles to `repeat(1, minmax(0, 1fr))`, the
189	    // same minmax `md:grid-cols-2` already applies, which is why desktop was fine.
190	    <div className="grid grid-cols-1 gap-6 md:grid-cols-2">
191	      <div className="card">
192	        <h2 className="mb-4 font-semibold">Access</h2>
193	        <dl className="space-y-3 text-sm">
194	          <div>
195	            <dt className="text-slate-400">SSH command</dt>
196	            <dd className="mt-1 flex items-center gap-2">
197	              <code className="rounded-lg border border-white/10 bg-navy-950/80 px-2.5 py-1.5 font-mono text-xs">
198	                {sshCommand ?? "provisioning…"}
199	              </code>
200	              {sshCommand && <CopyText text={sshCommand} />}
201	            </dd>
202	          </div>
203	          <div className="flex items-center justify-between">
204	            <dt className="text-slate-400">Root password</dt>
205	            <dd>
206	              {rootPassword ? (
207	                <RevealPassword password={rootPassword} />
208	              ) : (
209	                <span className="text-slate-500">—</span>
210	              )}
211	            </dd>
212	          </div>
213	          <div className="flex items-center justify-between">
214	            <dt className="text-slate-400">Private IP</dt>
215	            <dd className="font-mono text-xs">{server.ipAddress ?? "—"}</dd>
216	          </div>
217	        </dl>
218	        <div className="divider" />
219	        <div className="flex flex-wrap items-center justify-between gap-2">
220	          <p className="text-xs text-slate-500">
221	            Lost access or rotating credentials? Generate a fresh root password.
222	          </p>
223	          <ResetPasswordButton serverId={server.id} disabled={busy || !steady} />
224	        </div>
225	      </div>
226	
227	      <SftpAccess
228	        host={sftpHost}
229	        port={sftpPort}
230	        password={rootPassword}
231	        dedicated={dedicated}
232	      />
233	
234	      {isGameServer && (
235	        <div className="md:col-span-2">
236	          <GameAutoUpdate
237	            serverId={server.id}
238	            gameName={server.osTemplate.name}
239	            autoUpdate={server.autoUpdate}
240	            canUpdate={server.status === "RUNNING"}
241	            busy={busy}
242	          />
243	        </div>
244	      )}
245	
246	      {server.gamePlanId && gameSchema && (
247	        <div className="md:col-span-2">
248	          <GameSettings
249	            serverId={server.id}
250	            schema={gameSchema}
251	            variant={gameVariant}
252	            values={gameValues}
253	            disabled={busy || !steady}
254	          />
255	        </div>
256	      )}
257	
258	      <div className="card">
259	        <h2 className="mb-4 font-semibold">Live stats</h2>
260	        {live ? (
261	          <div className="space-y-4 text-sm">
262	            <div>
263	              <div className="mb-1.5 flex justify-between">
264	                <span className="text-slate-400">CPU</span>
265	                <span className="font-semibold">{((live.cpu ?? 0) * 100).toFixed(1)}%</span>
266	              </div>
267	              <MeterBar value={(live.cpu ?? 0) * 100} max={100} />
268	            </div>
269	            <div>
270	              <div className="mb-1.5 flex justify-between">
271	                <span className="text-slate-400">Memory</span>
272	                <span className="font-semibold">
273	                  {fmtBytes(live.mem ?? 0)} / {fmtBytes(live.maxmem ?? 0)}
274	                </span>
275	              </div>
276	              <MeterBar value={live.mem ?? 0} max={live.maxmem ?? 1} color="#3b82f6" />
277	            </div>
278	            <div className="flex justify-between">
279	              <span className="text-slate-400">Uptime</span>
280	              <span className="font-semibold">{fmtUptime(live.uptime ?? 0)}</span>
281	            </div>
282	            <div className="flex justify-between">
283	              <span className="text-slate-400">Network I/O</span>
284	              <span className="font-mono text-xs">
285	                {fmtBytes(live.netin ?? 0)} in · {fmtBytes(live.netout ?? 0)} out
286	              </span>
287	            </div>
288	          </div>
289	        ) : (
290	          <p className="text-sm text-slate-400">
291	            {pveUnavailable
292	              ? "Hypervisor is briefly unavailable — stats will reappear shortly."
293	              : "Live stats appear once the server is provisioned."}
294	          </p>
295	        )}
296	      </div>
297	
298	      <div className="card">
299	        <h2 className="mb-4 font-semibold">Configuration</h2>
300	        <dl className="space-y-2.5 text-sm">
301	          <div className="flex justify-between">
302	            <dt className="text-slate-400">Plan</dt>
303	            <dd>
304	              {server.plan.name} — {server.plan.cpuCores} vCPU / {server.plan.ramMB / 1024} GB /{" "}
305	              {totalDiskGB} GB NVMe
306	              {server.extraDiskGB > 0 && (
307	                <span className="block text-xs text-slate-500">
308	                  {server.plan.diskGB} GB plan + {server.extraDiskGB} GB added storage
309	                </span>
310	              )}
311	            </dd>
312	          </div>
313	          <div className="flex justify-between">
314	            <dt className="text-slate-400">Bandwidth</dt>
315	            <dd>{server.plan.bandwidthTB} TB / month</dd>
316	          </div>
317	          <div className="flex justify-between">
318	            <dt className="text-slate-400">Operating system</dt>
319	            <dd>{server.osTemplate.name}</dd>
320	          </div>
321	          <div className="flex justify-between">
322	            <dt className="text-slate-400">Created</dt>
323	            <dd>{server.createdAt.toISOString().slice(0, 10)}</dd>
324	          </div>
325	          <div className="flex justify-between">
326	            <dt className="text-slate-400">{server.isFree ? "Billing" : "Renews"}</dt>
327	            <dd>
328	              {server.isFree
329	                ? "Free — never expires"
330	                : server.expiresAt
331	                  ? server.expiresAt.toISOString().slice(0, 10)
332	                  : "—"}
333	            </dd>
334	          </div>
335	        </dl>
336	      </div>
337	
338	      {!server.isFree ? (
339	        <RenewalCard
340	          serverId={server.id}
341	          autoRenew={server.autoRenew}
342	          expiresAt={server.expiresAt ? server.expiresAt.toISOString() : null}
343	          priceCents={server.plan.priceCents}
344	          extraDiskGB={server.extraDiskGB}
345	          extraDiskMonthlyCents={server.extraDiskGB * extraDiskPriceCents}
346	          suspendedUnpaid={server.status === "SUSPENDED" && !!server.suspendedNote?.includes("unpaid")}
347	          renewTotalCents={renewQuote.totalCents}
348	          renewDurationLabel={renewQuote.durationLabel}
349	        />
350	      ) : (
351	        <div className="card">
352	          <h2 className="mb-3 font-semibold">Subscription</h2>
353	          <p className="text-sm text-slate-400">
354	            This server is free of charge — no billing, no expiry.
355	          </p>
356	        </div>
357	      )}
358	
359	      <div className="card md:col-span-2">
360	        <h2 className="mb-4 font-semibold">Disk usage</h2>
361	        <DiskUsageChart
362	          serverId={server.id}
363	          planTotalGB={totalDiskGB}
364	          available={!!server.vmid && steady}
365	        />
366	      </div>
367	
368	      <div className="card md:col-span-2">
369	        <h2 className="mb-3 font-semibold">Project</h2>
370	        <ProjectAssign
371	          serverId={server.id}
372	          currentProjectId={server.projectId}
373	          projects={projects.map((p) => ({ id: p.id, name: p.name, color: p.color }))}
374	        />
375	      </div>
376	    </div>
377	  );
378	
379	  /* ---------- Tab: Files ---------- */
380	  const filesPanel =
381	    server.status === "RUNNING" ? (
382	      <FileManager serverId={server.id} />
383	    ) : (
384	      <div className="card py-12 text-center">
385	        <h2 className="font-semibold">File manager unavailable</h2>
386	        <p className="mx-auto mt-2 max-w-md text-sm text-slate-400">
387	          The in-browser file manager works only while your server is{" "}
388	          <span className="font-medium text-slate-200">running</span>. Start the server to browse,
389	          upload, and edit files over SFTP.
390	        </p>
391	      </div>
392	    );
393	
394	  /* ---------- Tab: Snapshots ---------- */
395	  const snapshotsTab = (
396	    <div className="space-y-6">
397	      <div className="card">
398	        <h2 className="mb-4 font-semibold">Create snapshot</h2>
399	        <CreateSnapshotForm serverId={server.id} disabled={busy || !steady} />
400	      </div>
401	      <div className="card p-0">
402	        <p className="section-label px-4 pt-4">Snapshots</p>
403	        {pveUnavailable && snapshots.length === 0 ? (
404	          <p className="px-4 py-6 text-sm text-amber-300">
405	            Could not load snapshots — the hypervisor is briefly unavailable. Try again in a moment.
406	          </p>
407	        ) : snapshots.length === 0 ? (
408	          <p className="px-4 py-6 text-sm text-slate-400">
409	            No snapshots yet. Take one before risky changes so you can roll back instantly.
410	          </p>
411	        ) : (
412	          <table className="table-shell mt-2">
413	            <thead>
414	              <tr>
415	                <th>Name</th>
416	                <th>Taken</th>
417	                <th>Description</th>
418	                <th className="text-right">Actions</th>
419	              </tr>
420	            </thead>
421	            <tbody>
422	              {snapshots.map((s) => (
423	                <tr key={s.name}>
424	                  <td className="font-mono text-xs">{s.name}</td>
425	                  <td className="text-slate-400">
426	                    {s.snaptime ? new Date(s.snaptime * 1000).toISOString().slice(0, 16).replace("T", " ") : "—"}
427	                  </td>
428	                  <td className="text-slate-400">{s.description || "—"}</td>
429	                  <td>
430	                    <SnapshotActions serverId={server.id} name={s.name} disabled={busy || !steady} />
431	                  </td>
432	                </tr>
433	              ))}
434	            </tbody>
435	          </table>
436	        )}
437	      </div>
438	      <p className="text-xs text-slate-500">
439	        Snapshots live on the same storage as your server — use backups for disaster recovery.
440	      </p>
441	    </div>
442	  );
443	
444	  /* ---------- Tab: Backups ---------- */
445	  // Latest backup/restore job (server.jobs is desc by createdAt) — seeds the
446	  // live progress bar so a reloaded page shows an in-flight job without a flash.
447	  const latestBackupJob = server.jobs.find(
448	    (j) => j.type === "BACKUP_CREATE" || j.type === "BACKUP_RESTORE"
449	  );
450	  const initialBackupJob = latestBackupJob
451	    ? {
452	        id: latestBackupJob.id,
453	        type: latestBackupJob.type as "BACKUP_CREATE" | "BACKUP_RESTORE",
454	        status: latestBackupJob.status as "QUEUED" | "RUNNING" | "DONE" | "FAILED",
455	        progress: latestBackupJob.progress,
456	        step: latestBackupJob.step,
457	        error: latestBackupJob.error,
458	        createdAt: latestBackupJob.createdAt.toISOString(),
459	      }
460	    : null;
461	  // The schedule's honesty gate. `server.lastAutoBackup` now means "an archive
462	  // was seen in storage at this time" (incident H4 — it used to mean "a job row
463	  // was created"), and the last CREATE attempt supplies the failing/never cases.
464	  const lastBackupAttempt = server.jobs.find((j) => j.type === "BACKUP_CREATE");
465	  const backupHealth = backupScheduleHealth({
466	    now: Date.now(),
467	    autoBackup: server.autoBackup,
468	    intervalHours: server.backupIntervalHours,
469	    lastVerifiedAt: server.lastAutoBackup,
470	    lastAttempt: lastBackupAttempt
471	      ? { at: lastBackupAttempt.createdAt, status: lastBackupAttempt.status }
472	      : null,
