15	/**
16	 * Self-service restore: lists the server's vzdump backups and lets the owner
17	 * restore one, enqueuing a BACKUP_RESTORE job. Restore OVERWRITES the current
18	 * disk, so it is guarded by a typed/explicit confirm.
19	 */
20	export function BackupRestore({
21	  serverId,
22	  backups,
23	  unavailable,
24	  disabled,
25	}: {
26	  serverId: string;
27	  backups: Backup[];
28	  unavailable?: boolean;
29	  disabled?: boolean;
30	}) {
31	  const router = useRouter();
32	  const [error, setError] = useState<string | null>(null);
33	  const [pendingVolid, setPendingVolid] = useState<string | null>(null);
34	  const [isPending, start] = useTransition();
35	
36	  function restore(b: Backup) {
37	    const name = b.volid.split("/").pop() ?? b.volid;
38	    const ok = window.confirm(
39	      `Restore this server from backup:\n\n${name}\n(${fmtWhen(b.ctime)})\n\n` +
40	        "This OVERWRITES your server's current disk — every change made since this " +
41	        "backup will be permanently lost. The server is stopped, restored, then " +
42	        "started again.\n\nContinue?"
43	    );
44	    if (!ok) return;
45	    setPendingVolid(b.volid);
46	    start(async () => {
47	      setError(null);
48	      const res = await requestRestore(serverId, b.volid);
49	      setPendingVolid(null);
50	      if (res?.error) setError(res.error);
51	      else router.refresh();
52	    });
53	  }
54	
55	  return (
56	    <div className="card p-0">
57	      <div className="flex items-center justify-between px-4 pt-4">
58	        <p className="section-label">Restore from backup</p>
59	      </div>
60	
61	      {error && <p className="px-4 pt-2 text-sm text-red-400">{error}</p>}
62	
63	      {unavailable && backups.length === 0 ? (
64	        <p className="px-4 py-6 text-sm text-amber-300">
65	          Could not load backups — the hypervisor is briefly unavailable. Try again in a moment.
66	        </p>
67	      ) : backups.length === 0 ? (
68	        <p className="px-4 py-6 text-sm text-slate-400">
69	          No backups to restore yet. Create a backup above first — then you can roll the whole server
70	          back to it here.
71	        </p>
72	      ) : (
73	        <table className="table-shell mt-2">
74	          <thead>
75	            <tr>
76	              <th>Backup</th>
77	              <th>Created</th>
78	              <th className="text-right">Size</th>
79	              <th className="text-right">Actions</th>
80	            </tr>
81	          </thead>
82	          <tbody>
83	            {backups.map((b) => {
84	              const thisPending = isPending && pendingVolid === b.volid;
85	              return (
86	                <tr key={b.volid}>
87	                  <td className="font-mono text-xs">{b.volid.split("/").pop()}</td>
88	                  <td className="text-slate-400">{fmtWhen(b.ctime)}</td>
89	                  <td className="text-right text-slate-400">{fmtBytes(b.size ?? 0)}</td>
90	                  <td className="text-right">
91	                    <button
92	                      className="btn-danger px-3 py-1 text-xs"
93	                      disabled={disabled || isPending}
94	                      onClick={() => restore(b)}
95	                    >
96	                      {thisPending ? "Queueing…" : "Restore"}
97	                    </button>
98	                  </td>
99	                </tr>
100	              );
101	            })}
102	          </tbody>
103	        </table>
104	      )}
105	
106	      <p className="px-4 py-4 text-xs text-slate-500">
107	        Restoring overwrites the live disk with the backup&apos;s contents. Take a fresh backup first
108	        if you might want today&apos;s data back.
109	      </p>
110	    </div>
111	  );
112	}
