106	            : "Console disconnected — the relay or hypervisor may be unreachable."
107	        );
108	        rfbRef.current = null;
109	      });
110	      rfb.addEventListener("securityfailure", (e: any) => {
111	        setPhase("error");
112	        setMessage(`Console authentication failed${e?.detail?.reason ? `: ${e.detail.reason}` : "."}`);
113	      });
114	
115	      rfbRef.current = rfb;
116	    } catch (err) {
117	      setPhase("error");
118	      setMessage(err instanceof Error ? err.message : "failed to start the console");
119	    }
120	  }, [serverId, cleanup]);
121	
122	  const disconnect = useCallback(() => {
123	    cleanup();
124	    setPhase("idle");
125	    setMessage(null);
126	  }, [cleanup]);
127	
128	  const sendCtrlAltDel = useCallback(() => {
129	    try {
130	      rfbRef.current?.sendCtrlAltDel();
131	    } catch {
132	      /* ignore */
133	    }
134	  }, []);
135	
136	  const fullscreen = useCallback(() => {
137	    const el = containerRef.current?.parentElement;
138	    if (el?.requestFullscreen) void el.requestFullscreen();
139	  }, []);
140	
141	  const active = phase === "connecting" || phase === "connected";
142	
143	  return (
144	    <div className="space-y-4">
145	      <div className="flex flex-wrap items-center justify-between gap-3">
146	        <div>
147	          <h2 className="font-semibold">VNC console</h2>
148	          <p className="mt-1 text-sm text-slate-400">
149	            Direct graphical access to your server — useful when SSH or networking is unavailable.
150	          </p>
151	        </div>
152	        <div className="flex items-center gap-2">
153	          {active && (
154	            <>
155	              <button type="button" onClick={sendCtrlAltDel} className="btn-secondary">
156	                Ctrl+Alt+Del
157	              </button>
158	              <button type="button" onClick={fullscreen} className="btn-secondary">
159	                Fullscreen
160	              </button>
161	              <button type="button" onClick={disconnect} className="btn-danger">
162	                Disconnect
163	              </button>
164	            </>
165	          )}
166	          {!active && phase !== "unavailable" && (
167	            <button
168	              type="button"
169	              onClick={() => void connect()}
170	              className="btn-primary"
171	              disabled={phase === "loading"}
172	            >
173	              {phase === "loading" ? "Opening…" : "Open console"}
174	            </button>
175	          )}
176	        </div>
177	      </div>
178	
179	      {phase === "unavailable" ? (
180	        <div className="card border-amber-500/30 bg-amber-500/[0.06]">
181	          <div className="flex items-start gap-3">
182	            <svg
183	              width="20"
184	              height="20"
185	              viewBox="0 0 24 24"
186	              fill="none"
187	              stroke="#fbbf24"
188	              strokeWidth="1.6"
189	              className="mt-0.5 shrink-0"
190	            >
191	              <path d="M12 9v4M12 17h.01" />
192	              <path d="M10.3 3.9 1.8 18a2 2 0 0 0 1.7 3h17a2 2 0 0 0 1.7-3L13.7 3.9a2 2 0 0 0-3.4 0z" />
193	            </svg>
194	            <div>
195	              <h3 className="text-sm font-semibold text-amber-200">Console assets not installed</h3>
196	              <p className="mt-1 text-sm text-slate-400">
197	                The noVNC client bundle is missing. An operator can install it by running:
198	              </p>
199	              <code className="mt-2 inline-block rounded-lg border border-white/10 bg-navy-950/80 px-2.5 py-1.5 font-mono text-xs">
200	                scripts/fetch-novnc.sh
201	              </code>
202	            </div>
203	          </div>
204	        </div>
205	      ) : (
206	        <div className="relative overflow-hidden rounded-2xl border border-white/[0.08] bg-[#05060f]">
207	          <div
208	            ref={containerRef}
209	            className="flex min-h-[420px] w-full items-center justify-center"
210	          >
211	            {phase === "idle" && (
212	              <div className="px-6 py-16 text-center">
213	                <div className="mx-auto mb-4 w-fit rounded-2xl border border-white/[0.08] bg-gradient-to-br from-accent-blue/15 to-brand-500/15 p-4">
214	                  <svg width="28" height="28" viewBox="0 0 24 24" fill="none" stroke="#8a70fb" strokeWidth="1.5">
215	                    <rect x="2" y="4" width="20" height="14" rx="2" />
216	                    <path d="M8 21h8M12 18v3" />
217	                    <path d="m7 9 3 2-3 2M13 13h4" />
218	                  </svg>
219	                </div>
220	                <p className="text-sm text-slate-400">
221	                  The console opens a live graphical session. Click{" "}
222	                  <span className="font-medium text-slate-200">Open console</span> to connect.
223	                </p>
224	              </div>
225	            )}
226	            {(phase === "loading" || phase === "connecting") && (
227	              <div className="flex flex-col items-center gap-3 py-16 text-sm text-slate-400">
228	                <span className="h-6 w-6 animate-spin rounded-full border-2 border-white/20 border-t-brand-400" />
229	                {phase === "loading" ? "Requesting a secure ticket…" : "Connecting to the console…"}
230	              </div>
231	            )}
232	            {phase === "error" && (
233	              <div className="px-6 py-16 text-center">
234	                <p className="text-sm text-red-300">{message ?? "The console is unavailable."}</p>
235	                <button type="button" onClick={() => void connect()} className="btn-secondary mt-4">
236	                  Try again
237	                </button>
