401	/* Dock UI                                                                     */
402	/* -------------------------------------------------------------------------- */
403	
404	const STATUS_COLOR: Record<Status, string> = {
405	  connecting: "bg-amber-400 animate-pulse",
406	  connected: "bg-emerald-400",
407	  closed: "bg-slate-500",
408	  error: "bg-red-500",
409	};
410	
411	function IconBtn({
412	  onClick,
413	  label,
414	  children,
415	}: {
416	  onClick: () => void;
417	  label: string;
418	  children: React.ReactNode;
419	}) {
420	  return (
421	    <button
422	      onClick={onClick}
423	      aria-label={label}
424	      title={label}
425	      className="rounded-lg p-1.5 text-slate-400 transition-colors hover:bg-white/10 hover:text-white"
426	    >
427	      {children}
428	    </button>
429	  );
430	}
431	
432	function TerminalDock({
433	  sessions,
434	  activeId,
435	  mode,
436	  errors,
437	  attach,
438	  focusSession,
439	  closeSession,
440	  openSession,
441	  minimize,
442	  restore,
443	  close,
444	  reconnect,
445	}: {
446	  sessions: SessionMeta[];
447	  activeId: string | null;
448	  mode: Mode;
449	  errors: Record<string, string>;
450	  attach: (id: string, el: HTMLDivElement | null) => void;
451	  focusSession: (id: string) => void;
452	  closeSession: (id: string) => void;
453	  openSession: (server: TerminalServerRef) => void;
454	  minimize: () => void;
455	  restore: () => void;
456	  close: () => void;
457	  reconnect: (id: string) => void;
458	}) {
459	  const [pickerOpen, setPickerOpen] = useState(false);
460	  const [pickerLoading, setPickerLoading] = useState(false);
461	  const [pickerServers, setPickerServers] = useState<TerminalServerRef[]>([]);
462	  const [pickerError, setPickerError] = useState<string | null>(null);
463	  const minimized = mode === "minimized";
464	
465	  const activeMeta = sessions.find((s) => s.id === activeId) ?? null;
466	
467	  const loadPicker = useCallback(async () => {
468	    setPickerLoading(true);
469	    setPickerError(null);
470	    try {
471	      const all = await listTerminalServers();
472	      setPickerServers(all);
473	    } catch {
474	      setPickerError("Could not load your servers.");
475	    } finally {
476	      setPickerLoading(false);
477	    }
478	  }, []);
479	
480	  function togglePicker() {
481	    setPickerOpen((v) => {
482	      const next = !v;
483	      if (next) void loadPicker();
484	      return next;
485	    });
486	  }
487	
488	  // Servers not already open as tabs.
489	  const openIds = new Set(sessions.map((s) => s.id));
490	  const pickable = pickerServers.filter((s) => !openIds.has(s.id));
491	
492	  if (mode === "hidden" || sessions.length === 0) return null;
493	
494	  const outerClass = minimized
495	    ? "fixed bottom-4 left-1/2 z-[65] flex h-[280px] w-[460px] max-w-[92vw] -translate-x-1/2 flex-col overflow-hidden rounded-2xl border border-white/10 bg-navy-900 shadow-2xl shadow-black/50"
496	    // `lg:left-[var(--nx-rail-w,15rem)]`, not the old hardcoded `lg:left-60`. The
497	    // portal rail collapses to 4.75rem (components/portal/Shell.tsx) and this
498	    // never knew, so collapsing the sidebar left a ~10rem dead gutter down the
499	    // left of the terminal. Shell publishes the rail's live width on the document
500	    // element; 15rem is the uncollapsed default for any page that doesn't.
501	    : "fixed inset-x-0 bottom-0 z-[70] flex h-[70vh] max-h-[82vh] flex-col overflow-hidden border-t border-white/10 bg-navy-900 shadow-2xl shadow-black/50 lg:left-[var(--nx-rail-w,15rem)] lg:rounded-t-2xl lg:border-l";
502	
503	  return (
504	    <div className={outerClass} role="dialog" aria-label="Terminal dock">
505	      {/* Header + tab bar */}
506	      <div className="flex flex-none items-center gap-1.5 border-b border-white/[0.06] bg-white/[0.02] px-2 py-1.5">
507	        {/* Tabs */}
508	        <div className="flex min-w-0 flex-1 items-center gap-1 overflow-x-auto">
509	          {sessions.map((s) => {
510	            const active = s.id === activeId;
511	            return (
512	              <div
513	                key={s.id}
514	                className={`group flex flex-none items-center gap-1.5 rounded-lg border px-2.5 py-1.5 text-xs transition-colors ${
515	                  active
516	                    ? "border-white/15 bg-white/10 text-white"
517	                    : "border-transparent bg-transparent text-slate-400 hover:bg-white/[0.06] hover:text-slate-200"
518	                }`}
519	              >
520	                <button
521	                  onClick={() => focusSession(s.id)}
522	                  className="flex min-w-0 items-center gap-1.5"
523	                  title={s.hostname}
524	                >
525	                  <span className={`h-2 w-2 flex-none rounded-full ${STATUS_COLOR[s.status]}`} />
526	                  <span className="max-w-[8rem] truncate font-medium">{s.hostname}</span>
527	                </button>
528	                <button
529	                  onClick={() => closeSession(s.id)}
530	                  aria-label={`Close ${s.hostname}`}
531	                  className="flex-none rounded p-0.5 text-slate-500 hover:bg-white/10 hover:text-white"
532	                >
533	                  <svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.4" strokeLinecap="round">
534	                    <path d="M18 6 6 18M6 6l12 12" />
535	                  </svg>
536	                </button>
537	              </div>
538	            );
539	          })}
540	
541	          {/* "+" add-a-server picker */}
542	          {!minimized && (
543	            <div className="relative flex-none">
544	              <IconBtn onClick={togglePicker} label="Connect another server">
545	                <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round">
546	                  <path d="M12 5v14M5 12h14" />
547	                </svg>
548	              </IconBtn>
549	              {pickerOpen && (
550	                <div className="absolute left-0 top-9 z-10 w-64 overflow-hidden rounded-xl border border-white/10 bg-navy-900 shadow-2xl shadow-black/50">
551	                  <p className="border-b border-white/[0.06] px-3 py-2 text-[11px] font-semibold uppercase tracking-wider text-slate-500">
552	                    Open another server
553	                  </p>
554	                  <div className="max-h-56 overflow-y-auto py-1">
555	                    {pickerLoading ? (
556	                      <p className="px-3 py-3 text-xs text-slate-400">Loading…</p>
557	                    ) : pickerError ? (
558	                      <p className="px-3 py-3 text-xs text-red-300">{pickerError}</p>
559	                    ) : pickable.length === 0 ? (
560	                      <p className="px-3 py-3 text-xs text-slate-400">
561	                        No other running servers.
562	                      </p>
563	                    ) : (
564	                      pickable.map((s) => (
565	                        <button
566	                          key={s.id}
567	                          onClick={() => {
568	                            openSession(s);
569	                            setPickerOpen(false);
570	                          }}
571	                          className="flex w-full items-center gap-2 px-3 py-2 text-left text-xs text-slate-200 hover:bg-white/[0.06]"
572	                        >
573	                          <svg width="13" height="13" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.8">
574	                            <rect x="3" y="4" width="18" height="7" rx="2" />
575	                            <rect x="3" y="13" width="18" height="7" rx="2" />
576	                          </svg>
577	                          <span className="truncate">{s.hostname}</span>
578	                        </button>
579	                      ))
580	                    )}
581	                  </div>
582	                </div>
583	              )}
584	            </div>
585	          )}
586	        </div>
587	
588	        {/* Right controls */}
589	        <div className="flex flex-none items-center gap-0.5">
590	          {minimized ? (
591	            <IconBtn onClick={restore} label="Expand terminal">
592	              <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
593	                <path d="M15 3h6v6M9 21H3v-6M21 3l-7 7M3 21l7-7" />
594	              </svg>
595	            </IconBtn>
596	          ) : (
597	            <IconBtn onClick={minimize} label="Minimize terminal">
598	              <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round">
599	                <path d="M5 12h14" />
600	              </svg>
601	            </IconBtn>
602	          )}
603	          <IconBtn onClick={close} label="Close terminal dock">
604	            <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round">
605	              <path d="M18 6 6 18M6 6l12 12" />
606	            </svg>
607	          </IconBtn>
608	        </div>
609	      </div>
610	
611	      {/* Terminal surface — every session container lives here at once; only the
612	          active one is shown. This subtree keeps the SAME nodes across
613	          minimize↔restore so xterm/socket are never recreated. */}
614	      <div className="relative min-h-0 flex-1 bg-[#0a0e1a] p-1.5">
615	        {sessions.map((s) => (
616	          <div
617	            key={s.id}
618	            ref={(el) => attach(s.id, el)}
619	            className="absolute inset-1.5"
620	            style={{ display: s.id === activeId ? "block" : "none" }}
621	          />
622	        ))}
623	      </div>
624	
625	      {/* Reconnect strip for the active session when its socket dropped. */}
626	      {activeMeta && (activeMeta.status === "closed" || activeMeta.status === "error") && (
627	        <div className="flex flex-none items-center gap-3 border-t border-white/[0.06] bg-white/[0.02] px-3 py-1.5 text-xs">
628	          <span className={activeMeta.status === "error" ? "text-red-300" : "text-slate-400"}>
629	            {errors[activeMeta.id] || (activeMeta.status === "error" ? "Error" : "Disconnected")}
630	          </span>
631	          <button
632	            onClick={() => reconnect(activeMeta.id)}
633	            className="ml-auto rounded-lg border border-white/10 bg-white/5 px-2.5 py-1 font-semibold text-slate-200 hover:bg-white/10"
634	          >
635	            Reconnect
636	          </button>
637	        </div>
638	      )}
639	    </div>
640	  );
641	}
