1	import { StatusDot, timeAgo } from "@/components/ui/primitives";
2	
3	/** A job as needed by the timeline — plain data, safe from a server component. */
4	export type TimelineJob = {
5	  id: string;
6	  type: string;
7	  status: string;
8	  attempts: number;
9	  payload: unknown;
10	  error: string | null;
11	  createdAt: Date;
12	  updatedAt: Date;
13	};
14	
15	const TITLES: Record<string, string> = {
16	  PROVISION: "Server deployed",
17	  START: "Powered on",
18	  STOP: "Powered off",
19	  REBOOT: "Rebooted",
20	  REINSTALL: "Reinstalled OS",
21	  DELETE: "Deleted",
22	  SUSPEND: "Suspended",
23	  UNSUSPEND: "Unsuspended",
24	  RESIZE: "Resized plan",
25	  DISK_EXPAND: "Storage added",
26	  SNAPSHOT_CREATE: "Snapshot created",
27	  SNAPSHOT_DELETE: "Snapshot deleted",
28	  SNAPSHOT_ROLLBACK: "Rolled back to snapshot",
29	  BACKUP_CREATE: "Backup created",
30	  PASSWORD_RESET: "Root password reset",
31	  SYNC_FORWARDS: "Networking updated",
32	};
33	
34	/** Human-readable detail from a job's payload. */
35	function describePayload(type: string, payload: unknown, planNames: Record<string, string>): string | null {
36	  if (!payload || typeof payload !== "object") return null;
37	  const p = payload as Record<string, unknown>;
38	  if (type === "RESIZE" && typeof p.planId === "string") {
39	    return `→ ${planNames[p.planId] ?? "new plan"}`;
40	  }
41	  if (type === "DISK_EXPAND" && typeof p.addGB === "number") {
42	    // Growth is one-way, so this is always a "+" — never a reduction.
43	    return `+${p.addGB} GB (permanent)`;
44	  }
45	  if (type.startsWith("SNAPSHOT_") && typeof p.name === "string") {
46	    return `“${p.name}”`;
47	  }
48	  return null;
49	}
50	
51	function dotClass(status: string): string {
52	  if (status === "DONE") return "bg-emerald-400";
53	  if (status === "FAILED") return "bg-red-400";
54	  if (status === "RUNNING") return "bg-amber-400 animate-pulse-dot";
55	  return "bg-slate-500";
56	}
57	
58	export function ActivityTimeline({
59	  jobs,
60	  planNames,
61	}: {
62	  jobs: TimelineJob[];
63	  planNames: Record<string, string>;
64	}) {
65	  if (jobs.length === 0) {
66	    return <p className="px-4 py-6 text-sm text-slate-400">No activity recorded for this server yet.</p>;
67	  }
68	  return (
69	    <ol className="relative space-y-5 px-5 py-5">
70	      <span className="absolute bottom-2 left-[9px] top-2 w-px bg-white/10" aria-hidden />
71	      {jobs.map((j) => {
72	        const detail = describePayload(j.type, j.payload, planNames);
73	        return (
74	          <li key={j.id} className="relative flex gap-4 pl-6">
75	            <span
76	              className={`absolute left-0 top-1.5 h-[10px] w-[10px] rounded-full ring-4 ring-navy-900 ${dotClass(j.status)}`}
77	              aria-hidden
78	            />
79	            <div className="min-w-0 flex-1">
80	              <div className="flex flex-wrap items-center gap-x-2 gap-y-1">
81	                <span className="font-medium">{TITLES[j.type] ?? j.type.toLowerCase().replace(/_/g, " ")}</span>
82	                {detail && <span className="font-mono text-xs text-slate-400">{detail}</span>}
83	                <StatusDot status={j.status} />
84	                {j.attempts > 1 && (
85	                  <span className="text-xs text-slate-500">· {j.attempts} attempts</span>
86	                )}
87	              </div>
88	              {j.status === "FAILED" && j.error && (
89	                <p className="mt-1 max-w-xl truncate text-xs text-red-400" title={j.error}>
90	                  {j.error}
91	                </p>
92	              )}
93	            </div>
94	            <time className="shrink-0 text-xs text-slate-500">{timeAgo(j.createdAt)}</time>
95	          </li>
96	        );
97	      })}
98	    </ol>
99	  );
100	}
